"""
Per-script file-existence guarantee.

For every input file each experiment's scripts read at runtime, this
suite asserts the file is reachable on disk under the wired
`shared_data/` layout. The test is partitioned into:

  * **raw inputs** — files that ship with the data drop (Recon3D SBML,
    TCGA expression matrices, HMA pseudolabels, GPR table, multi-seed
    predictions). These MUST exist for any user to run the pipeline.
    Failures here are blocking.

  * **intermediate artifacts** — files generated by an earlier stage of
    the pipeline (`hma_labels_thresholded.pt`, `splits.json`,
    `graph_structure.pt`, training-checkpoint `*.pt`, `test_scores.npz`).
    These are NOT raw inputs; they only exist after a user has run the
    upstream training scripts. We document them but don't fail when
    absent.

  * **download-on-demand** — files behind a data-use agreement
    (METABRIC, CPTAC-BRCA raw matrices, TCGA-LUAD raw STAR counts).
    These are documented in their respective `shared_data/<name>/README.md`
    but skipped by this test.

The strongest reproducibility statement this suite makes is:
**after `bash experiments/scripts/wire_shared_data.sh` runs cleanly,
every raw-input file that any script tries to open exists on disk.**
"""

from __future__ import annotations

from pathlib import Path

import pytest

from _paths import EXPERIMENTS_DIR, JOURNALS_DIR, SHARED_DATA_DIR


# ─────────────────────────────────────────────────────────────────────
# Helpers
# ─────────────────────────────────────────────────────────────────────


def _exists(p: Path | str) -> bool:
    """True iff the path (or its symlink target) resolves to a real file/dir."""
    try:
        return Path(p).resolve(strict=False).exists()
    except OSError:
        return False


def _check(label: str, path: Path) -> None:
    """Helper for richer fail messages on `assert _exists`."""
    p = path.resolve(strict=False) if path.is_absolute() else path
    assert _exists(path), (
        f"Missing canonical input: {label}\n"
        f"  Expected at: {path}\n"
        f"  Resolves to: {p}\n"
        f"  Fix: run `bash experiments/scripts/wire_shared_data.sh` "
        f"or restore the source-of-truth tree."
    )


