def test_intermediate_artifacts_documented():
    """Documentation-only test: lists pipeline-output files that
    *aren't* raw inputs. Always passes; serves as developer guidance."""
    msg = ["The following are PIPELINE OUTPUTS, not raw inputs:"]
    for desc, paths in _INTERMEDIATE_ARTIFACTS:
        msg.append(f"\n{desc}")
        for p in paths:
            full = JOURNALS_DIR / p
            present = "✓" if _exists(full) else "—"
            msg.append(f"  {present} {p}")
    # Always passes; just print the inventory.
    print("\n".join(msg))


# ─────────────────────────────────────────────────────────────────────
# Regression: no script ships hardcoded personal paths
# ─────────────────────────────────────────────────────────────────────


@pytest.mark.smoke
def test_no_hardcoded_personal_paths_in_runnable_scripts():
    """Catch regressions: no runnable script under experiments/ should
    ship a /Users/... or /home/<user>/... path in code (not counting
    comments/docstrings)."""
    bad_patterns = (
        "/Users/<user>",
        "/sessions/<session>",
        "/home/<user>",
    )
    offenders = []
    scripts = list(EXPERIMENTS_DIR.rglob("*.py")) + list(EXPERIMENTS_DIR.rglob("*.sh"))
    for py in scripts:
        if "__pycache__" in py.parts or "/tests/" in str(py):
            continue
        text = py.read_text(encoding="utf-8", errors="replace")
        for lineno, line in enumerate(text.splitlines(), 1):
            stripped = line.lstrip()
            if stripped.startswith(("#", '"', "'")):
                continue
            for pat in bad_patterns:
                if pat in line:
                    offenders.append(f"{py}:{lineno}: {line.strip()}")
    if offenders:
        msg = "\n".join(offenders[:20])
        pytest.fail(
            f"{len(offenders)} hardcoded personal path(s) in runnable scripts:\n{msg}"
        )
